            &lt;mat-error *ngIf="myForm.get('emailFc')?.hasError('required')"&gt;
                Email is required
            &lt;/mat-error&gt;
            &lt;mat-error *ngIf="myForm.get('emailFc')?.hasError('email')"&gt;
                Invalid email format
            &lt;/mat-error&gt;

        &lt;/mat-form-field&gt;

        &lt;!-- Number --&gt;
        &lt;mat-form-field appearance="outline" class="mx-2"&gt;
            &lt;mat-label&gt;Age&lt;/mat-label&gt;
            &lt;input matInput type="number" formControlName="ageFc"&gt;
        &lt;/mat-form-field&gt;

        &lt;!-- Password --&gt;
        &lt;mat-form-field appearance="outline" class="mx-2"&gt;
            &lt;mat-label&gt;Password&lt;/mat-label&gt;
            &lt;input matInput type="password" formControlName="passwordFc"&gt;
        &lt;/mat-form-field&gt;

        &lt;!-- File Upload --&gt;
        &lt;div class="mx-2"&gt;
            &lt;label&gt;Upload Resume&lt;/label&gt;&lt;br /&gt;
            &lt;input type="file" (change)="onFileSelected($event)"&gt;
        &lt;/div&gt;

        &lt;!-- Multi-Select Dropdown --&gt;
        &lt;mat-form-field appearance="outline" class="mx-2"&gt;
           &lt;mat-form-field appearance="outline" class="mx-2"&gt;
            &lt;mat-label&gt;Select Skills&lt;/mat-label&gt;
            &lt;mat-select formControlName="skillsFc" multiple&gt;
                &lt;mat-checkbox class="" (change)="onSelectall($event)"
             &gt;
                All&lt;/mat-checkbox&gt;
                &lt;mat-option *ngFor="let skill of skills" [value]="skill"&gt;{{ skill }}&lt;/mat-option&gt;
            &lt;/mat-select&gt;
